for f in glob.glob("lessons/*/*/task.json"):
    t = json.load(open(f, encoding="utf-8")); i = t["id"]
    if i in S: t["steps"] = S[i]
    if i in P: t["sample"] = P[i]
    json.dump(t, open(f, "w", encoding="utf-8"), ensure_ascii=False, indent=2); open(f, "a").write("\n")
